To create a basic API using Node.js and Express:

```javascript
// 1. Install Express: npm install express

// 2. Create app.js
const express = require('express');
const app = express();
const PORT = 3000;

// Middleware to parse JSON
app.use(express.json());

// GET route
app.get('/api/items', (req, res) => {
  res.json({ message: 'GET all items', items: [] });
});

// GET single item
app.get('/api/items/:id', (req, res) => {
  res.json({ message: `GET item ${req.params.id}` });
});

// POST route
app.post('/api/items', (req, res) => {
  const newItem = req.body;
  res.status(201).json({ message: 'Item created', item: newItem });
});

// PUT route
app.put('/api/items/:id', (req, res) => {
  res.json({ message: `Item ${req.params.id} updated`, data: req.body });
});

// DELETE route
app.delete('/api/items/:id', (req, res) => {
  res.json({ message: `Item ${req.params.id} deleted` });
});

// Start server
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

Key concepts: Express routes handle HTTP methods (GET, POST, PUT, DELETE), `req.params` accesses URL parameters, `req.query` accesses query strings, and `req.body` accesses the request body (requires JSON middleware). Use `res.json()` to send JSON responses and `res.status()` to set HTTP status codes. For production, add error handling middleware, input validation, and connect to a database like MongoDB or PostgreSQL.
